let raffleLastLog = "";function unbiasedRandomIndex(max){const range = 256 - (256 % max);let byte;do{byte = crypto.getRandomValues(new Uint8Array(1))[0];}while (byte >= range);return byte % max;}function drawWithoutReplacement(pool, count){const remaining = [...pool];const winners = [];for (let i = 0;i < count && remaining.length;i++){const idx = unbiasedRandomIndex(remaining.length);winners.push(remaining[idx]);remaining.splice(idx, 1);}return winners;}function executeRaffleDraw(){const allowDupes = document.getElementById("raffle-allow-repeat-entries").checked;let entries = document.getElementById("raffle-entries").value.split("\n").map((e) => e.trim()).filter(Boolean);if (!allowDupes) entries = [...new Set(entries)]; const winnerCount = Math.max(1, parseInt(document.getElementById("raffle-winner-count").value, 10) || 1);const out = document.getElementById("raffle-result");const log = document.getElementById("raffle-log");const copyBtn = document.getElementById("raffle-copy-log-btn");if (!entries.length){GAMA.say("idle");out.textContent = "";log.textContent = "";copyBtn.style.display = "none";return;}if (winnerCount > entries.length){out.textContent = `// only ${entries.length} entries, can't pick ${winnerCount} unique winners`;GAMA.say("error");return;}const winners = drawWithoutReplacement(entries, winnerCount);out.innerHTML = winners.map((w, i) => `${winnerCount > 1 ? `#${i + 1}: ` : ""}${w}`).join("<br>");const timestamp = new Date().toISOString();raffleLastLog = [ `RAFFLE DRAW LOG`, `timestamp (UTC): ${timestamp}`, `total entries: ${entries.length}`, `winners drawn: ${winnerCount}`, ``, `full entry list:`, ...entries.map((e, i) => `  ${i + 1}. ${e}`), ``, `result:`, ...winners.map((w, i) => `  #${i + 1}: ${w}`), ].join("\n");log.textContent = raffleLastLog;copyBtn.style.display = "";GAMA.say("success");}document.addEventListener("DOMContentLoaded", () =>{document.getElementById("raffle-copy-log-btn").addEventListener("click", () =>{navigator.clipboard.writeText(raffleLastLog);GAMA.log("Copied raffle proof log");GAMA.say("success");});});